    cos_actual = evaluate(FunctionNode("cos", NumberNode(value)), angle_mode)
    assert _agree_10(sin_actual, S.reference_sin(value, angle_mode))
    assert _agree_10(cos_actual, S.reference_cos(value, angle_mode))


